import { useEffect, useState } from 'react';
import $ from 'jquery';
import Container from 'react-bootstrap/Container';
import ToastContainer from 'react-bootstrap/ToastContainer';
import Toast from 'react-bootstrap/Toast';
import './contact.css'

//// TODO
// - retirar os botoes e meter a funcionar em modo

function Contact() {

    const [showToast, setShowToast] = useState(false);
    
    function sendEmail() {
        var subject = document.getElementById("subject").value;
        var body = document.getElementById("body").value;
        if (subject !== "" && body !== "") {
            console.log("here");
            var sendemail = document.getElementById("sendmail");
            sendemail.href = `mailto:filipeg@ua.pt?subject=${document.getElementById("subject").value}&body=${document.getElementById("body").value}`;
            sendemail.click();
            $("#toast").css("background-color", "rgba(var(--text-color), 0.8) !important")
            $("#toast-message").text("Successfully sent an email!! Thank you for your time!")
            $("#toast-header").text("Success")
            setShowToast(true);
        } else {
            $("#toast").css("background-color", "rgba(var(--bs-danger-rgb), 0.8) !important")
            $("#toast-message").text("Something went wrong... couldn't send email")
            $("#toast-header").text("Error")
            setShowToast(true);
        }
    }

    return (
        <Container fluid className="card-container home vh-100" style={{ color: "white" }}>
            <div class="container h-100">
                <div class="row h-100 aling-vertical">
                    <div class="header">
                        <div class="header-content">
                            <h1 class="header-title">Contact Me</h1>
                            <div class="background-information py-5">
                                <h4 class="header-mono">Send me an email</h4>
                                <input class="btn btn-rounded mt-4 btn-resume w-75 textarea-contact" type="text" placeholder="Subject *" id="subject" required />
                                <textarea class="btn btn-rounded mt-4 btn-resume w-75 textarea-contact mx-5" type="text" placeholder="Message *" id="body" style={{minHeight: "200px"}} required></textarea>
                                <button class="btn btn-rounded mt-4 btn-resume mx-5" onClick={sendEmail}>
                                    Send Email
                                    <a id="sendmail" href="" hidden></a>
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <ToastContainer
                className="p-3"
                position="top-end"
                style={{ zIndex: 1 }}
            >
                <Toast 
                    show={showToast} 
                    onClose={() => setShowToast(false)} 
                    animation={true}
                    delay={3000} autohide
                    style={{backgroundColor: "transparent"}}
                >
                    <Toast.Header
                        className='toast-header-bg'
                        id="toast"
                    >
                        <strong className="me-auto" id="toast-header"></strong>
                        <small>Now</small>
                    </Toast.Header>
                    <Toast.Body
                        className='toast-bg'
                        id="toast-message"
                    ></Toast.Body>
                </Toast>
            </ToastContainer>
        </Container>
    );
}

export default Contact;