function clicksidebar(index) {
    var current_index = $("section.active")[0].id.replaceAll("section", "")
    if (index == current_index)
        return

    var sections = $(".section")
    var pixels =  (current_index - index) * 100;

    console.log(current_index)
    $("#section"+current_index).removeClass("active")
    $("#icon"+current_index).removeClass("active")
    $("#icon"+current_index).next().removeClass("active")
    document.getElementsByClassName("dock-panel")[0].children[current_index-1].classList.remove("active")
    $.each(sections, (i) => {
        sections[i].style.left = (+sections[i].style.left.replace("vw", "") + pixels) + "vw"
    })
    $("#section"+index).addClass("active")
    $("#icon"+index).addClass("active")
    $("#icon"+index).next().addClass("active")
    document.getElementsByClassName("dock-panel")[0].children[index-1].classList.add("active")
}

