import { useEffect, useState } from 'react';
import { Accordion, Container } from 'react-bootstrap';
import $ from 'jquery';
import '../assets/fontawesome/css/all.css'
import './repository.css'
import AnimatedList from '../AnimatedList/AnimatedList'

function Repository() {

    const [projects, setProjects] = useState([]);
    const [projectsShow, setProjectsShow] = useState([]);
    const [tags, setTags] = useState([]);
    const [owners, setOwners] = useState([]);

    function moreInfo(element) {
        var div = $("#" + element.name.replaceAll(".", "") + "Div")[0]

        if (element.languages == undefined) {

            console.log("here")

            $.ajax({
                type: 'GET',
                url: element.languages_url,
                dataType: "json",
                success: function (languages) {
                    element.languages = Object.keys(languages)
                    var htmllanguages = ""
                    element.languages.forEach(el => {
                        htmllanguages += `<span class="badge bg-warning me-1" style="cursor: pointer">${el}</span>`
                    })

                    $("#" + element.name.replaceAll(".", "") + "Langs")[0].innerHTML = htmllanguages
                    div.style.height = div.style.height == "auto" ? 0 : "auto"
                    div.style.paddingBottom = div.style.paddingBottom == "0px" ? "3rem" : "0px"
                    div.style.paddingTop = div.style.paddingTop == "0px" ? "3rem" : "0px"
                    div.style.opacity = div.style.opacity == 1 ? 0 : 1
                }
            })
        }
        else {
            div.style.height = div.style.height == "auto" ? 0 : "auto"
            div.style.paddingBottom = div.style.paddingBottom == "0px" ? "3rem" : "0px"
            div.style.paddingTop = div.style.paddingTop == "0px" ? "3rem" : "0px"
            div.style.opacity = div.style.opacity == 1 ? 0 : 1
        }
    }

    function filter() {

        var topic = document.querySelectorAll("[id*=tag_]:checked")
        var owner = document.querySelectorAll("[id*=owner_]:checked")

        setProjectsShow([])
        projects.forEach(el => {

            console.log(el)

            var valid_owner = false
            owner.forEach(t => {
                if (el.owner.login == t.value) {
                    valid_owner = true
                    return
                }
            })

            if (valid_owner || owner.length == 0) {
                if (topic.length == 0) {
                    setProjectsShow(projectsShow => [...projectsShow, el]);
                    return
                }

                var valid_topic = false
                topic.forEach(t => {
                    if (el.topics.includes(t.value)) {
                        valid_topic = true
                        return
                    }
                })

                if (valid_topic)
                    setProjectsShow(projectsShow => [...projectsShow, el]);

            }

        });
    }

    function checkall(query, cid) {
        document.querySelectorAll(query).forEach((el) => el.checked = document.getElementById(cid).checked)
        filter()
    }

    var count = 0
    useEffect(() => {
        if (count == 0) {
            count = 1
            $.ajax({
                type: 'GET',
                url: 'https://api.github.com/users/FlipGoncalves/repos',
                dataType: "json",
                data: { type: "all", per_page: 100, sort: "pushed" },
                success: function (repos) {

                    console.log(repos)

                    // mini db
                    setProjects(repos)

                    // temp dictionary for topics
                    var tagstemp = {}
                    var ownerstemp = []

                    // Get New Repositories
                    setProjectsShow([])
                    repos.forEach(el => {

                        el.topics.forEach(topic => {
                            if (tagstemp[topic]) {
                                tagstemp[topic] += 1;
                            } else {
                                tagstemp[topic] = 1;
                            }
                        });

                        var topics_temp = [];
                        el.topics.forEach(el => {
                            topics_temp.push(
                                <span className="badge bg-secondary me-1" style={{ cursor: 'pointer' }}>{el}</span>
                            )
                        });

                        var dt = new Date(Date.parse(el.pushed_at));
                        el.date_published = dt.getFullYear() + "/" + (+dt.getMonth() + 1) + "/" + (+dt.getDay() + 1);

                        var dif = Date.now() - Date.parse(el.pushed_at)
                        dif = dif / (1000 * 60 * 60 * 24 * 365)                     // By Year
                        if (dif < 0.5) {
                            topics_temp.push(
                                <span className="badge bg-danger me-1" style={{ cursor: 'pointer' }}>New</span>
                            )
                            el.topics.push("new")
                        }
                        el.topics_temp = topics_temp

                        ownerstemp.push(el.owner.login)
                        setProjectsShow(projectsShow => [...projectsShow, el]);
                    });

                    var topics = Object.entries(tagstemp);
                    topics.sort((a, b) => b[1] - a[1])
                    var sortedTags = Object.fromEntries(topics);
                    setTags(["new"].concat(Object.keys(sortedTags)))

                    setOwners([...new Set(ownerstemp)])

                    $.ajax({
                        type: 'GET',
                        url: 'https://api.github.com/orgs/FotoFaces/repos',
                        dataType: "json",
                        data: { type: "all", per_page: 100, sort: "pushed" },
                        success: function (repos) {
                            console.log(repos)

                            // temp dictionary for topics
                            var tagstemp = {}
                            var ownerstemp = []

                            repos.forEach(el => {
                                el.topics.forEach(topic => {
                                    if (tagstemp[topic]) {
                                        tagstemp[topic] += 1;
                                    } else {
                                        tagstemp[topic] = 1;
                                    }
                                });

                                var topics_temp = [];
                                el.topics.forEach(el => {
                                    topics_temp.push(
                                        <span className="badge bg-secondary me-1" style={{ cursor: 'pointer' }}>{el}</span>
                                    )
                                });

                                var dt = new Date(Date.parse(el.pushed_at));
                                el.date_published = dt.getFullYear() + "/" + (+dt.getMonth() + 1) + "/" + (+dt.getDay() + 1);
                                var dif = Date.now() - Date.parse(el.pushed_at)
                                dif = dif / (1000 * 60 * 60 * 24 * 365)                     // By Year
                                if (dif < 0.5) {
                                    topics_temp.push(
                                        <span className="badge bg-danger me-1" style={{ cursor: 'pointer' }}>New</span>
                                    )
                                    el.topics.push("new")
                                }
                                el.topics_temp = topics_temp

                                ownerstemp.push(el.owner.login)
                                setProjects(projects => [...projects, el])
                                setProjectsShow(projectsShow => [...projectsShow, el]);
                            });

                            var topics = Object.entries(tagstemp);
                            topics.sort((a, b) => b[1] - a[1])
                            var sortedTags = Object.fromEntries(topics);
                            Object.keys(sortedTags).forEach((t) => {
                                setTags(tags => [...tags, t])
                            })

                            setOwners(owners => [...owners, ...new Set(ownerstemp)])
                        }
                    })
                }
            });
        }
    }, [])

    if (document.body.clientWidth > 1000) {
        document.querySelectorAll(".accordion-body.position-absolute").forEach((el) => {
            el.classList.remove("position-absolute")
        })
    }   

    return (
        <Container fluid className="card-container overflow-hidden vh-100" style={{ color: "white" }}>
            <div class="container-fluid vh-100" id="void">
                <div class="row h-100 my-3">
                    <div class="col-lg-2 col-12">
                        <Accordion defaultActiveKey={['0', '1']} alwaysOpen>
                            <Accordion.Item eventKey="0" className='animation-rep'>
                                <Accordion.Header>Topics</Accordion.Header>
                                <Accordion.Body className="overflow-y-scroll position-absolute" style={{ maxHeight: "40vh", zIndex: '10' }}>
                                    <div class="form-check">
                                        <input class="form-check-input" type="checkbox" value='' id='checkall_tag' onChange={() => checkall("[id*=tag_]", "checkall_tag")} />
                                        <label class="form-check-label">All</label>
                                    </div>
                                    {tags.map(topic => {
                                        return (
                                            <div class="form-check">
                                                <input class="form-check-input" type="checkbox" value={topic} id={"tag_" + topic} onChange={() => filter()} />
                                                <label class="form-check-label" htmlFor={"tag_" + topic}>{topic}</label>
                                            </div>
                                        )
                                    })}
                                </Accordion.Body>
                            </Accordion.Item>
                            <Accordion.Item eventKey="1" className='animation-rep'>
                                <Accordion.Header>Owners</Accordion.Header>
                                <Accordion.Body className="overflow-y-scroll position-absolute" style={{ maxHeight: "40vh", zIndex: '9' }}>
                                    <div class="form-check">
                                        <input class="form-check-input" type="checkbox" value='' id='checkall_owner' onChange={() => checkall("[id*=owner_]", "checkall_owner")} />
                                        <label class="form-check-label">All</label>
                                    </div>
                                    {owners.map(owner => {
                                        return (
                                            <div class="form-check">
                                                <input class="form-check-input" type="checkbox" value={owner} id={"owner_" + owner} onChange={() => filter()} />
                                                <label class="form-check-label" htmlFor={"owner_" + owner}>{owner}</label>
                                            </div>
                                        )
                                    })}
                                </Accordion.Body>
                            </Accordion.Item>
                        </Accordion>
                    </div>
                    <div class="col-lg-10 col-12">
                        <AnimatedList className='w-100 h-100'
                            items={projectsShow}
                            onItemSelect={(item, index) => moreInfo(item)}
                            showGradients={false}
                            enableArrowNavigation={true}
                            displayScrollbar={true}
                        />
                    </div>
                </div>
            </div>
        </Container>
    );
}

export default Repository;